#!/usr/bin/env python3
import os
import sys


def main() -> int:
    log_path = os.environ.get("BOT_LOG_PATH", "/workspace/reimpl/bot_log_blank.stdin")
    with open(log_path, "w", encoding="utf-8") as log:
        while True:
            line = sys.stdin.readline()
            if line == "":
                return 0
            log.write(repr(line) + "\n")
            log.flush()
            sys.stdout.write("\n")
            sys.stdout.flush()


if __name__ == "__main__":
    raise SystemExit(main())

